/**
 * The census export, read by the Vitest half of the brand guard and the frozen-identifier
 * test (feature 015; FTID §3.7, §3.8, CF-16, CF-25 m5).
 *
 * `docs/legacy-identifiers.md` is generated by miSuite `census.py --export miForge` and never
 * edited here. Python's reader (`backend/tests/support/legacy_identifiers.py`) and this one
 * each compile the pattern dialect their own engine runs: `pattern` there, `pattern_js` with
 * `js_flags` here. The private repository reads the full file; the public mirror only has
 * `legacy-identifiers.public.md`.
 */
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';

export const REPO_ROOT = path.resolve(__dirname, '../../..');
export const PHASES = ['P0', 'P1', 'P2', 'P3', 'P4', 'P5', 'P6', 'P7', 'P8'] as const;

export interface Entry {
  readonly id: string;
  readonly status: string;
  readonly pattern: string;
  readonly pattern_js: string;
  readonly js_flags: string;
  readonly literals: readonly string[];
  readonly exercise: string | null;
  readonly flags: readonly string[];
}

export interface Rename {
  readonly old: string;
  readonly new: string;
  readonly status: string;
}

export interface Guard {
  readonly id: string;
  readonly pattern_js: string;
  readonly js_flags: string;
  readonly effect: 'deny' | 'allow';
  readonly from_phase: string | null;
  readonly until_phase: string | null;
}

export interface Header {
  readonly format: number;
  readonly variant: string;
  readonly phase: string;
  readonly closed: string | null;
  readonly withheld: readonly string[];
}

export interface Export {
  readonly header: Header;
  readonly entries: readonly Entry[];
  readonly env: readonly Rename[];
  readonly repo: readonly Rename[];
  readonly guards: readonly Guard[];
}

export function exportPath(root = REPO_ROOT): string {
  const full = path.join(root, 'docs', 'legacy-identifiers.md');
  if (existsSync(full)) return full;
  const pub = path.join(root, 'docs', 'legacy-identifiers.public.md');
  if (existsSync(pub)) return pub;
  throw new Error(`neither ${full} nor ${pub} exists: generate them with census.py --export`);
}

const INLINE_FLAG = /\(\?[a-zA-Z]+[:)]/;

export function phaseIndex(phase: string | null): number {
  if (phase === null) return -1;
  const index = (PHASES as readonly string[]).indexOf(phase);
  if (index < 0) throw new Error(`unknown phase ${phase}`);
  return index;
}

export function parseExport(text: string): Export {
  const block = /^```jsonl\n([\s\S]*?)^```\s*$/m.exec(text);
  if (!block?.[1]) throw new Error('no ```jsonl block in the export');
  const records = block[1]
    .split('\n')
    .filter((line) => line.trim() !== '')
    .map((line) => JSON.parse(line) as Record<string, unknown>);
  const header = records[0] as unknown as Header;
  if (header.format !== 1) throw new Error(`export format ${String(header.format)} is not 1`);
  if (!('closed' in header)) throw new Error('export header lacks closed (CF-21)');
  const of = <T>(section: string): T[] =>
    records.slice(1).filter((r) => r['section'] === section) as unknown as T[];
  const entries = of<Entry>('entry');
  const guards = of<Guard>('guard');
  for (const record of [...entries, ...guards]) {
    const where = (record as { id: string }).id;
    if (record.js_flags !== '' && record.js_flags !== 'i') {
      throw new Error(`${where}: js_flags ${record.js_flags} is not '' or 'i'`);
    }
    if (INLINE_FLAG.test(record.pattern_js)) {
      throw new Error(`${where}: pattern_js carries an inline flag group (CF-16)`);
    }
  }
  return { header, entries, env: of<Rename>('env'), repo: of<Rename>('repo'), guards };
}

export function loadExport(root = REPO_ROOT): Export {
  return parseExport(readFileSync(exportPath(root), 'utf8'));
}

export function compileJs(
  record: { pattern_js: string; js_flags: string },
  global = false,
): RegExp {
  return new RegExp(record.pattern_js, `${global ? 'g' : ''}${record.js_flags}`);
}

export function activeGuards(exported: Export, phase: string = exported.header.phase): Guard[] {
  const now = phaseIndex(phase);
  return exported.guards.filter(
    (g) =>
      now >= phaseIndex(g.from_phase ?? 'P0') &&
      (g.until_phase === null || now < phaseIndex(g.until_phase)),
  );
}

export function withHeader(exported: Export, changes: Partial<Header>): Export {
  return { ...exported, header: { ...exported.header, ...changes } };
}

/**
 * Is `root` the public mirror's snapshot? The same predicate as
 * `backend/tests/support/mirror_snapshot.py`: HEAD is ONE parentless commit carrying both
 * trailers the sync writes (`Source-Commit: <sha>` and `Private-CI: passed`). A private commit
 * has a parent and no trailers. No git, or no repository: false - so the brand guard, which
 * reports only on the mirror (suite R23), enforces everywhere it cannot prove it is there.
 */
export function mirrorSnapshot(root = REPO_ROOT): boolean {
  const git = (...args: string[]): string | null => {
    try {
      return execFileSync('git', args, { cwd: root, encoding: 'utf8', stdio: 'pipe' });
    } catch {
      return null;
    }
  };
  const parents = git('rev-list', '--parents', '-n', '1', 'HEAD');
  const trailers = git('log', '-1', '--format=%(trailers:only,unfold)', 'HEAD');
  if (parents === null || trailers === null) return false;
  if (parents.trim().split(/\s+/).length !== 1) return false;
  const lines = trailers.split('\n');
  return (
    lines.includes('Private-CI: passed') &&
    lines.some((l) => /^Source-Commit: [0-9a-f]{40}$/.test(l))
  );
}
